// GitHub HMAC-SHA256 signature verification, opt-in.
// Header: X-Hub-Signature-256 with format `sha256=<hex>`.
// Enable by setting GITHUB_WEBHOOK_SECRET + WEBHOOK_INTEGRITY_CHECK_ENABLED=1.

const secret = $env.GITHUB_WEBHOOK_SECRET;
const integrityCheckEnabled = $env.WEBHOOK_INTEGRITY_CHECK_ENABLED === '1';

if (!secret || !integrityCheckEnabled) {
  return [$input.first()];
}

const crypto = require('crypto');
const item = $input.first();
const rawBody = item.json.rawBody || (typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body || {}));
const headers = item.json.headers || {};
const sigHeader = headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'];

if (!sigHeader || typeof sigHeader !== 'string') {
  throw new Error('UNAUTHORIZED: missing X-Hub-Signature-256 header');
}

// Strip the `sha256=` prefix
if (!sigHeader.startsWith('sha256=')) {
  throw new Error('UNAUTHORIZED: malformed signature header (expected sha256= prefix)');
}
const providedSig = sigHeader.slice('sha256='.length);

const expected = crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');

if (providedSig.length !== expected.length) {
  throw new Error('UNAUTHORIZED: signature length mismatch');
}

const expBuf = Buffer.from(expected, 'utf8');
const provBuf = Buffer.from(providedSig, 'utf8');
if (!crypto.timingSafeEqual(expBuf, provBuf)) {
  throw new Error('UNAUTHORIZED: invalid signature');
}

return [$input.first()];

// Per-IP sliding-window rate limit, opt-in. Same pattern as the other templates.

if ($env.RATE_LIMIT_ENABLED !== '1') {
  return [$input.first()];
}

const LIMIT = 60;
const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 5000;

const item = $input.first();
const headers = item.json.headers || {};
const rawIp = headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown';
const key = String(rawIp).split(',')[0].trim();

const data = $getWorkflowStaticData('global');
data.rateBuckets = data.rateBuckets || {};
const buckets = data.rateBuckets;
const now = Date.now();

for (const k of Object.keys(buckets)) {
  buckets[k] = (buckets[k] || []).filter(t => now - t < WINDOW_MS);
  if (buckets[k].length === 0) delete buckets[k];
}
if (Object.keys(buckets).length > MAX_KEYS) {
  const oldest = Object.entries(buckets).sort((a, b) => (a[1][0] || 0) - (b[1][0] || 0)).slice(0, 100);
  for (const [k] of oldest) delete buckets[k];
}

const hits = buckets[key] || [];
if (hits.length >= LIMIT) {
  throw new Error('RATE_LIMIT_EXCEEDED: ' + LIMIT + ' requests per ' + Math.round(WINDOW_MS / 60000) + ' minutes for ' + key);
}
buckets[key] = [...hits, now];

return [$input.first()];

// 5-minute idempotency window on X-GitHub-Delivery, opt-in.
// GitHub's per-delivery UUID is the canonical idempotency key.

if ($env.IDEMPOTENCY_ENABLED !== '1') {
  return [$input.first()];
}

const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 10000;

const item = $input.first();
const headers = item.json.headers || {};
const deliveryId = headers['x-github-delivery'] || headers['X-GitHub-Delivery'];

if (!deliveryId) {
  return [$input.first()];
}

const data = $getWorkflowStaticData('global');
data.seenKeys = data.seenKeys || {};
const seen = data.seenKeys;
const now = Date.now();

for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}
if (Object.keys(seen).length > MAX_KEYS) {
  const oldest = Object.entries(seen).sort((a, b) => a[1] - b[1]).slice(0, 1000);
  for (const [k] of oldest) delete seen[k];
}

if (seen[deliveryId]) {
  // Duplicate detected. Emit a sentinel item that the
  // 'Skip If Duplicate' IF node routes to 'Respond Duplicate'
  // (200 OK + { deduped: true }). Without that 200 the source
  // provider would hold the HTTP connection until n8n's webhook
  // timeout (default 30s) and mark delivery failed.
  return [{ json: { skipped: true, reason: 'duplicate', dedupKey: String(deliveryId) } }];
}
seen[deliveryId] = now;

return [$input.first()];

// Filter event types. Only forward issues.opened / reopened / labeled.
// GitHub sends one webhook per `Issues` event. The action field tells us which.
// Returns [] (empty array) for non-forwarded actions so the branch halts cleanly.

const body = $input.first().json.body || {};
const action = body.action || 'unknown';
const FORWARD_ACTIONS = ['opened', 'reopened', 'labeled'];

if (!FORWARD_ACTIONS.includes(action)) {
  // Halt branch. Returning [] (not a sentinel object) prevents downstream nodes
  // from running with empty data and creating blank tracker tickets.
  return [];
}

return [$input.first()];

// Normalize GitHub issue payload into a stable schema.

const body = $input.first().json.body || {};
const issue = body.issue || {};
const repo = body.repository || {};
const sender = body.sender || {};
const headers = $input.first().json.headers || {};

const labels = Array.isArray(issue.labels) ? issue.labels.map(l => String(l && l.name || '').toLowerCase()).filter(Boolean) : [];

return [{
  json: {
    deliveryId: headers['x-github-delivery'] || headers['X-GitHub-Delivery'] || ('unknown-' + Date.now()),
    action: body.action,
    issueNumber: issue.number,
    issueId: issue.id,
    issueTitle: issue.title || 'Untitled',
    issueBody: issue.body || '',
    issueUrl: issue.html_url,
    issueState: issue.state,
    repoFullName: repo.full_name,
    repoUrl: repo.html_url,
    reporterLogin: sender.login,
    labels,
    receivedAt: new Date().toISOString(),
  },
}];

// Classify the issue type from labels. Bug / feature / chore are the canonical buckets.
// Override the rubric for your team's labels.

const input = $input.first().json;
const labels = input.labels || [];

let issueType = 'task';
let priority = 'normal';

if (labels.some(l => /bug|defect|broken|regression/.test(l))) issueType = 'bug';
else if (labels.some(l => /feature|enhancement|request/.test(l))) issueType = 'feature';
else if (labels.some(l => /chore|maintenance|refactor|cleanup/.test(l))) issueType = 'chore';
else if (labels.some(l => /docs|documentation/.test(l))) issueType = 'docs';

if (labels.some(l => /critical|p0|urgent|sev-1/.test(l))) priority = 'urgent';
else if (labels.some(l => /high|p1|sev-2/.test(l))) priority = 'high';
else if (labels.some(l => /low|p3|p4/.test(l))) priority = 'low';

return [{
  json: {
    ...input,
    issueType,
    priority,
  },
}];

// Pick tracker target from env. Default linear.

const input = $input.first().json;
const trackerTarget = ($env.TRACKER_TARGET || 'linear').toLowerCase();

return [{
  json: {
    ...input,
    trackerTarget,
  },
}];

