// Normalize tracker response into a unified shape.
// Linear returns { data: { issueCreate: { issue: { id, identifier, url, title } } } }
// Jira returns { id, key, self }
// ClickUp returns { id, name, url, ... }

const input = $input.first();
const body = input.json || {};

let trackerId = null;
let trackerUrl = null;
let trackerLabel = null;

if (body.data && body.data.issueCreate && body.data.issueCreate.issue) {
  const iss = body.data.issueCreate.issue;
  trackerId = iss.id;
  trackerUrl = iss.url;
  trackerLabel = iss.identifier || iss.title || iss.id;
} else if (body.key && body.self) {
  trackerId = body.id;
  trackerLabel = body.key;
  // Jira self looks like https://X.atlassian.net/rest/api/2/issue/<id>; build browse URL
  const baseMatch = String(body.self).match(/^(https?:\/\/[^\/]+)/);
  trackerUrl = baseMatch ? (baseMatch[1] + '/browse/' + body.key) : null;
} else if (body.id && body.url) {
  trackerId = body.id;
  trackerUrl = body.url;
  trackerLabel = body.id;
}

return [{
  json: {
    ...body,
    trackerId,
    trackerUrl,
    trackerLabel,
    trackerSuccess: !!trackerId,
  },
}];

// Fallback for tracker / comment failures.

const input = $input.first();
const err = (input.json && input.json.error) || input.error || {};
const orig = ($('Set Tracker Target').first() && $('Set Tracker Target').first().json) || {};

return [{
  json: {
    ok: false,
    fallback: true,
    deliveryId: orig.deliveryId || 'unknown',
    issueNumber: orig.issueNumber,
    repoFullName: orig.repoFullName,
    trackerTarget: orig.trackerTarget || 'unknown',
    error: {
      message: err.message || 'unknown error',
      name: err.name || 'TrackerError',
    },
    receivedAt: orig.receivedAt || new Date().toISOString(),
  },
}];
